"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2631],{52631:d=>{d.exports=JSON.parse('{"schemaVersion":1,"locale":"ru","slug":"00-vvedenie","title":"Урок 00. Введение: Зачем начинать не с инвестиций","sourceFingerprint":"061a0c076ec8d55f6603f6074962c9e63e5e6563a6c624cb58a1f59530e8cd9a","blocks":[{"id":"b001","markdown":"## Введение"},{"id":"b002","markdown":"Зачем начинать не с инвестиций"},{"id":"b003","markdown":"Большинство начинает разбираться с деньгами с конца. Открывают брокерский счёт, покупают пару акций, потому что все покупают, читают про крипту. А параллельно платят 50% годовых по кредитке и не могут сказать, сколько тратят в месяц. Примерно как ставить турбину на машину, у которой течёт масло. Мощности станет больше, но поедешь ты недолго."},{"id":"b004","markdown":"Этот модуль про то, что стоит сделать до инвестиций. Скучная часть, которую почти все пропускают, а потом теряют на бирже больше, чем там заработали."},{"id":"b005","markdown":"### Почему именно сейчас"},{"id":"b006","markdown":"Несколько цифр осени 2026 года. Средняя начисленная зарплата в июле, по данным Росстата, 109 524 ₽. Это до вычета НДФЛ и это среднее, а не медиана, так что большинство получает меньше. Ключевая ставка Банка России на 23 октября 14%. Годовая инфляция в сентябре, по Росстату, 6,35%."},{"id":"b007","markdown":"Полная стоимость кредита по кредитным картам в июне, по данным Объединённого кредитного бюро, около 50% годовых. А средняя максимальная ставка по вкладам в 10 крупнейших банках, по мониторингу ЦБ на вторую декаду октября, 13,06%. Если сложить это вместе, получается такая картина: рубль в долге сейчас стоит от 25 до 50% в год, а рубль на вкладе приносит около 13%."},{"id":"b008","markdown":"Можно получать одинаковую зарплату и жить в 2 разных экономиках. В одной ты каждый месяц отдаёшь банку проценты, в другой банк платит их тебе. С каждым месяцем расстояние между ними только растёт."},{"id":"b009","markdown":"Цифры на сегодня"},{"id":"b010","markdown":"Ключевая ставка на 23 октября 14% Инфляция за год в сентябре 2026 6,35% Максимальная ставка по вкладам в среднем по 10 крупнейшим банкам, вторая декада октября 13,06% Цифры в тексте даны на день, когда урок писался. Актуальные значения проверяйте на официальном сайте Банка России."},{"id":"b011","markdown":"ОДНА ЗАРПЛАТА, ДВЕ ЭКОНОМИКИ ТЫ В ДОЛГЕ БАНК 25–50% В ГОД ПЛАТИШЬ ТЫ ТЫ С ВКЛАДОМ БАНК ~13% В ГОД ПЛАТЯТ ТЕБЕ С КАЖДЫМ МЕСЯЦЕМ РАССТОЯНИЕ РАСТЁТ"},{"id":"b012","markdown":"### Кому подойдёт"},{"id":"b013","markdown":"Если зарплата приходит, а к концу месяца непонятно, куда она делась. Если висит один или несколько кредитов и кажется, что так будет всегда. Если ты уже пробовал откладывать, но деньги каждый раз \xabпонадобились\xbb. Или если хочется начать инвестировать, но непонятно, готов ли ты к этому."},{"id":"b014","markdown":"Если долгов нет, подушка на полгода есть и откладываешь ты каждый месяц, часть уроков покажется очевидной. Тогда загляни хотя бы в уроки 7, 9 и 10, про мошенников, банк и вычеты. Именно там люди чаще всего теряют деньги по невнимательности."},{"id":"b015","markdown":"### В каком порядке"},{"id":"b016","markdown":"- Урок 1. Сколько ты стоишь и что считать богатством."},{"id":"b017","markdown":"- Урок 2. Куда уходят деньги."},{"id":"b018","markdown":"- Урок 3. Как откладывать без силы воли."},{"id":"b019","markdown":"- Урок 4. Какие долги нормальные, а какие тебя съедают."},{"id":"b020","markdown":"- Урок 5. Как выбраться из плохих долгов."},{"id":"b021","markdown":"- Урок 6. Финансовая подушка."},{"id":"b022","markdown":"- Урок 7. Как не отдать всё мошенникам."},{"id":"b023","markdown":"- Урок 8. Инфляция, сложный процент и что проверить перед первой инвестицией."},{"id":"b024","markdown":"- Урок 9. Как сделать, чтобы банк зарабатывал меньше на тебе и больше для тебя."},{"id":"b025","markdown":"- Урок 10. Налоговые вычеты."},{"id":"b026","markdown":"В конце модуля 2 гайда. Первый: план на 30 дней, 10 шагов, которые можно отмечать по мере выполнения. Второй: как пользоваться кредиткой бесплатно, для тех, у кого уже нет долгов и есть подушка. Порядок здесь важнее любого инструмента. Пока не закрыты дорогие долги и нет подушки, любая инвестиция превращается в лотерею. Первая же неприятность заставит продать бумаги в худший момент или снова залезть в кредитку."},{"id":"b027","markdown":"### Как устроен модуль"},{"id":"b028","markdown":"Урок читается минут за 10–15. В конце каждого есть 3 контрольных вопроса, чтобы самому проверить, что главное осело в голове. Цифры актуальны на октябрь 2026 года и взяты у Росстата, Банка России, ФНС и бюро кредитных историй. Ставки и законы меняются, материалы будем обновлять."},{"id":"b029","markdown":"Какие акции купить, здесь не будет. \xabТемки\xbb на удвоение дохода и обещаний разбогатеть за месяц тоже. Это не индивидуальная инвестиционная рекомендация, а механика, решения принимаешь ты. Прежде чем открыть первый урок, ответь себе честно на один вопрос: сколько месяцев ты проживёшь, если завтра зарплата не придёт?"}],"terms":[{"id":"inflyatsiya","term":"Инфляция","definition":"рост общего уровня цен. На деле: денег стало больше, товаров столько же — каждый стоит дороже. Ты не стал богаче, просто ценники выросли"},{"id":"klyuchevaya-stavka","term":"Ключевая ставка","definition":"процент, под который ЦБ кредитует банки. Главный инструмент денежно-кредитной политики и \xabцена денег\xbb в экономике. Ставка вверх — кредиты дороже, инфляция тормозит"},{"id":"kreditnaya-istoriya","term":"Кредитная история","definition":"запись о том, как ты платил по кредитам. Плохая история или её отсутствие = отказ или ставка выше рыночной. Пустая история хуже, чем история с погашенными кредитами"},{"id":"nalogovyy-vychet","term":"Налоговый вычет","definition":"возврат части уплаченных налогов государством. До 260 000 ₽ за покупку квартиры, 13% за лечение и образование. Реальные деньги, которые люди не забирают, потому что не знают"},{"id":"ndfl","term":"НДФЛ (налог на доходы физических лиц)","definition":"Налог на доходы физических лиц. В учебных расчётах этого курса используются 13% до 2,4 млн ₽ годового дохода и 15% для следующей ступени. С 2025 года основная шкала прогрессивная; для других видов дохода действуют особые правила. Актуальные ставки и право на вычет проверяйте у ФНС."},{"id":"slozhnyy-protsent","term":"Сложный процент","definition":"когда проценты начисляются на проценты. Главный союзник долгосрочного инвестора: 10 000 ₽ сейчас через 20 лет стоят больше, чем 100 000 ₽ через 10 лет"}],"quizzes":[],"officialSources":[]}')}}]);